// System Call: Requesting process creation (Privileged operation)
// Kernel handles allocating resources and setting up state.
pid_t pid = fork();

if (pid == 0) {
    // Child context: Call execve (another syscall)
    // Kernel must load new code and reset process memory layout.
    char *const argv[] = {"/bin/date", NULL};
    execve("/bin/date", argv, NULL);
    _exit(1); // Only executed if execve fails
}

if (pid > 0) {
    // Parent context: Wait for child termination (waitpid syscall)
    int status;
    waitpid(pid, &status, 0);
}

